css:
.loader {
  position: relative;
  width: 26px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 11px;
  background: repeating-linear-gradient(#6366f1 0 4px, transparent 4px 8px);
}
.loader::after {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 11px;
  background: repeating-linear-gradient(transparent 0 4px, #6366f1 4px 8px);
}
.loader i {
  position: absolute;
  left: 50%;
  top: 0;
  width: 10px;
  height: 9px;
  margin-left: -5px;
  border-radius: 2px;
  background: #4338ca;
  z-index: 2;
  animation: zip 1.5s ease-in-out infinite;
}
@keyframes zip {
  0% { top: 0; }
  50% { top: calc(100% - 9px); }
  100% { top: 0; }
}
